from rest_framework import viewsets, permissions
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import ClinicalTrialSubject
from .serializers import TrialSubjectSerializer

class ClinicalTrialSubjectViewSet(viewsets.ModelViewSet):
    permission_classes = [permissions.IsAuthenticated]
    serializer_class = TrialSubjectSerializer

    def get_queryset(self):
        # Restrict active records to sites where the investigator is assigned
        return ClinicalTrialSubject.objects.filter(
            trial_site__investigators=self.request.user
        )

    @action(detail=True, methods=['post'])
    def restore_subject(self, request, pk=None):
        # Restrict soft-deleted record lookup strictly to investigator's assigned sites
        subject = ClinicalTrialSubject.deleted_objects.filter(
            pk=pk,
            trial_site__investigators=request.user
        ).first()

        if not subject:
            return Response({"error": "Subject not found or access denied"}, status=404)

        subject.undelete()
        return Response({
            "subject_id": subject.id,
            "patient_code": subject.anonymized_code,
            "status": "RESTORED"
        })
